// @ts-nocheck – scaffold generated by scripts/build-manifest.mjs; props mirror the manifest's Figma properties.
// Fill FIGMA_NODE_URL once the kit exists, then run `pnpm figma:connect` to publish.
import figma from '@figma/code-connect';
import { DescriptionList } from '@davinci-ai/react';

const FIGMA_NODE_URL = 'FIGMA_NODE_URL'; // e.g. https://www.figma.com/design/<file>?node-id=<id>  (Data/DescriptionList)

figma.connect(DescriptionList, FIGMA_NODE_URL, {
  props: {
    layout: figma.enum('layout', { 'inline': 'inline', 'stacked': 'stacked' }),
  },
  example: ({ layout }) => (
    <DescriptionList layout={layout}></DescriptionList>
  ),
});
